import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const f=JSON.parse('{"title":"Εγκατάσταση και ανάπτυξη","description":"","frontmatter":{},"headers":[],"relativePath":"el/installation/index.md","filePath":"el/installation/index.md"}'),n={name:"el/installation/index.md"};function r(s,e,o,p,_,d){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="εγκατασταση-και-αναπτυξη" tabindex="-1">Εγκατάσταση και ανάπτυξη <a class="header-anchor" href="#εγκατασταση-και-αναπτυξη" aria-label="Permalink to &quot;Εγκατάσταση και ανάπτυξη&quot;">​</a></h1><p>Ο οδηγός περιγράφει την προετοιμασία ενός εγκεκριμένου περιβάλλοντος TransferBook+, την ένταξη μιας επιχείρησης στην πλατφόρμα και την ασφαλή διαχείριση εκδόσεων. Συμπληρώνει τις <a href="/el/system-requirements/">απαιτήσεις συστήματος</a>.</p><p>Η αγγλική τεκμηρίωση είναι η πηγή αναφοράς. Η πλήρης ελληνική απόδοση θα ενταχθεί στην προγραμματισμένη επικαιροποίηση μεταφράσεων.</p><ul><li>Η πρόσβαση μέσω προγράμματος περιήγησης δεν απαιτεί τοπική εγκατάσταση βάσης δεδομένων ή περιβάλλοντος εκτέλεσης.</li><li>Η διαχειριζόμενη ή αποκλειστική φιλοξενία και η εγκατάσταση σε υποδομή του πελάτη προϋποθέτουν εγκεκριμένη διάθεση και συμφωνημένους όρους υποστήριξης. Ο οδηγός δεν αποτελεί προσφορά αυτοδιαχειριζόμενης εγκατάστασης.</li><li>Πριν από την έναρξη λειτουργίας, επιβεβαιώστε την έκδοση, τα δικαιώματα, τις περιοχές, τον στόλο, τους οδηγούς, την τιμολόγηση και τα εγκεκριμένα κανάλια κρατήσεων.</li><li>Διαχωρίστε τα περιβάλλοντα παραγωγής, δοκιμών και επίδειξης. Χρησιμοποιήστε συνθετικά δεδομένα στις δοκιμές.</li><li>Πριν από κάθε αναβάθμιση, ελέγξτε τα αντίγραφα ασφαλείας, τη δυνατότητα ανάκτησης, τις αλλαγές στη βάση δεδομένων και τα κριτήρια αποδοχής.</li><li>Ελέγξτε τις κρατήσεις χωρίς υποχρεωτικό email επιβάτη, τις αναθέσεις και τις ενεργές διασυνδέσεις πριν δεχθείτε πραγματικές κρατήσεις.</li></ul><p><a href="/installation/">Πλήρης οδηγός Installation &amp; Deployment (English)</a></p><p><a href="/el/release-notes/">Σημειώσεις εκδόσεων</a> · <a href="/el/help/">Κέντρο βοήθειας</a></p><p>Πριν από την έναρξη λειτουργίας, δείτε <a href="/el/security-privacy/">Ασφάλεια, ιδιωτικότητα και ΓΚΠΔ</a>.</p>',7)])])}const m=a(n,[["render",r]]);export{f as __pageData,m as default};
